import { Context, Effect, Layer, ManagedRuntime } from "effect";
import { RpcClient, type RpcClientError } from "effect/rpc";
import { RendererRpcClient } from "electron-effect-rpc/renderer";
import { NotesRpc } from "./notes.ts";

class NotesApi extends Context.Service<
  NotesApi,
  RpcClient.FromGroup<typeof NotesRpc, RpcClientError.RpcClientError>
>()("app/NotesApi") {}

/** Acquire a scoped MessagePort RPC client for the desktop renderer. */
export function createNotesClient() {
  const api = Layer.effect(NotesApi, RpcClient.make(NotesRpc)).pipe(
    Layer.provide(RendererRpcClient.layerProtocol()),
  );

  const runtime = ManagedRuntime.make(api);

  return {
    list: (signal: AbortSignal) =>
      runtime
        .runPromise(
          Effect.gen(function* () {
            const client = yield* NotesApi;

            return { notes: yield* client.ListNotes(), error: "" };
          }).pipe(
            Effect.catch(() => Effect.succeed({ notes: [], error: "Notes could not be loaded." })),
          ),
          { signal },
        )
        .catch(() => ({ notes: [], error: "" })),
    add: (text: string) =>
      runtime.runPromise(
        Effect.gen(function* () {
          const client = yield* NotesApi;

          return { note: yield* client.AddNote({ text }), error: "" };
        }).pipe(
          Effect.catch(() =>
            Effect.succeed({ note: undefined, error: "The note could not be saved." }),
          ),
        ),
      ),
    dispose: () => runtime.dispose(),
  };
}

tests/database-files.test.ts:
import { Effect } from "effect";
import { copyFile, mkdtemp, readFile, readdir, rm, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { DatabaseSync } from "node:sqlite";
import { expect, test } from "vite-plus/test";
import { exportDatabase, migrateDatabase, restoreDatabase } from "../desktop/database-files.ts";

test("an upgrade backs up real data; export and restore recover it", async () => {
  const root = await mkdtemp(join(tmpdir(), "database-files-"));
  const migrations = join(root, "migrations");
  const backups = join(root, "backups");
  const filename = join(root, "app.sqlite");
  const { mkdir } = await import("node:fs/promises");
  await mkdir(migrations);
  await copyFile("migrations/0001_notes.sql", join(migrations, "0001_notes.sql"));

  const migrate = () =>
    Effect.runPromise(Effect.scoped(migrateDatabase(filename, migrations, backups)));

  try {
    await migrate();
    const initial = new DatabaseSync(filename);
    initial.prepare("INSERT INTO notes(text) VALUES (?)").run("Keep this note");
    initial.close();
    await writeFile(
      join(migrations, "0002_add_settings.sql"),
      "CREATE TABLE settings (name TEXT PRIMARY KEY); CREATE INDEX notes_text ON notes(text);",
    );
    await migrate();
    const snapshot = (await readdir(backups))[0];
    expect(snapshot).toBeDefined();
    const exported = join(root, "export.sqlite");
    await Effect.runPromise(Effect.scoped(exportDatabase(filename, exported)));
    const current = new DatabaseSync(filename);
    current.exec("DELETE FROM notes");
    current.close();
    await Effect.runPromise(
      Effect.scoped(restoreDatabase(filename, exported, migrations, backups)),
    );
    const restored = new DatabaseSync(filename);
    expect(restored.prepare("SELECT text FROM notes").all()).toEqual([{ text: "Keep this note" }]);
    expect(
      restored.prepare("SELECT name FROM sqlite_master WHERE name = 'notes_text'").all(),
    ).toHaveLength(1);
    restored.close();
    const applied = await readFile(join(migrations, "0002_add_settings.sql"), "utf8");
    await writeFile(join(migrations, "0002_add_settings.sql"), applied + " -- edited");
    await expect(migrate()).rejects.toThrow();
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

test("failed migrations roll back and corrupt restore files leave data intact", async () => {
  const root = await mkdtemp(join(tmpdir(), "database-failure-"));
  const migrations = join(root, "migrations");
  const backups = join(root, "backups");
  const filename = join(root, "app.sqlite");
  const { mkdir } = await import("node:fs/promises");
  await mkdir(migrations);
  await copyFile("migrations/0001_notes.sql", join(migrations, "0001_notes.sql"));

  try {
    await Effect.runPromise(Effect.scoped(migrateDatabase(filename, migrations, backups)));
    await writeFile(
      join(migrations, "0002_broken.sql"),
      "CREATE TABLE partial (id INTEGER); THIS IS NOT SQL;",
    );
    await expect(
      Effect.runPromise(Effect.scoped(migrateDatabase(filename, migrations, backups))),
    ).rejects.toThrow();
    const database = new DatabaseSync(filename);
    expect(database.prepare("SELECT name FROM sqlite_master WHERE name = 'partial'").all()).toEqual(
      [],
    );
    database.close();
    const corrupt = join(root, "bad.sqlite");
    await writeFile(corrupt, "invalid database");
    await expect(
      Effect.runPromise(Effect.scoped(restoreDatabase(filename, corrupt, migrations, backups))),
    ).rejects.toThrow();
    const preserved = new DatabaseSync(filename);
    expect(
      preserved.prepare("SELECT count(*) AS count FROM __project_kit_migrations").get(),
    ).toEqual({ count: 1 });
    preserved.close();
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

tests/e2e/notes.spec.ts:
import { _electron as electron, expect, test } from "@playwright/test";
import { mkdtemp, rm } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join } from "node:path";

test("desktop RPC persists a note across app restarts", async () => {
  const directory = await mkdtemp(join(tmpdir(), "desktop-smoke-"));

  const environment = Object.fromEntries(
    Object.entries(process.env).flatMap(([key, value]) =>
      value === undefined || key === "ELECTRON_RUN_AS_NODE" ? [] : [[key, value]],
    ),
  );

  const options: Parameters<typeof electron.launch>[0] = {
    args: ["."],
    env: { ...environment, PROJECT_KIT_DATA_DIRECTORY: directory },
  };

  const executable = process.env.PROJECT_KIT_EXECUTABLE;

  if (executable !== undefined) {
    options.executablePath = executable;
    options.args = [];
  }

  const launch = () => electron.launch(options);

  const app = await launch();

  try {
    const page = await app.firstWindow();
    await expect(page.getByRole("button", { name: "Save note" })).toBeEnabled();
    await page.getByLabel("New note").fill("Saved through Electron RPC");
    await page.getByRole("button", { name: "Save note" }).click();
    await expect(page.getByRole("list", { name: "Saved notes" })).toContainText(
      "Saved through Electron RPC",
    );
  } finally {
    await app.close();
  }

  const restarted = await launch();

  try {
    const page = await restarted.firstWindow();
    await expect(page.getByRole("list", { name: "Saved notes" })).toContainText(
      "Saved through Electron RPC",
    );
  } finally {
    await restarted.close();
    await rm(directory, { recursive: true, force: true });
  }
});

